-- Ingredients per restaurant (grouped by kitchen post or area, each with the place where it is stored) and what is missing right now.
CREATE TABLE ingredient_groups (
  id            INTEGER PRIMARY KEY AUTOINCREMENT,
  restaurant_id INTEGER NOT NULL REFERENCES restaurants(id) ON DELETE CASCADE,
  name_fr       TEXT NOT NULL,
  name_en       TEXT NOT NULL,
  post_id       INTEGER REFERENCES posts(id) ON DELETE SET NULL,
  position      INTEGER NOT NULL DEFAULT 0
);
CREATE INDEX idx_ingredient_groups ON ingredient_groups (restaurant_id, position);
CREATE TABLE ingredients (
  id       INTEGER PRIMARY KEY AUTOINCREMENT,
  group_id INTEGER NOT NULL REFERENCES ingredient_groups(id) ON DELETE CASCADE,
  name     TEXT NOT NULL,
  location TEXT NOT NULL DEFAULT 'fridge',   -- fridge | freezer | backstore | basement
  position INTEGER NOT NULL DEFAULT 0
);
CREATE INDEX idx_ingredients_group ON ingredients (group_id, position);
-- Missing right now at a restaurant: the shopping list for the fridge, freezer, back store and basement.
CREATE TABLE restock_needs (
  restaurant_id INTEGER NOT NULL REFERENCES restaurants(id) ON DELETE CASCADE,
  ingredient_id INTEGER NOT NULL REFERENCES ingredients(id) ON DELETE CASCADE,
  requested_by  INTEGER REFERENCES staff(id) ON DELETE SET NULL,
  requested_at  INTEGER NOT NULL,
  PRIMARY KEY (restaurant_id, ingredient_id)
);
